def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    # find diagonal same-color chains of length>=2, extend both directions until edge or non-bg
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    seen=set()
    for r in range(h):
        for c in range(w):
            col=g[r][c]
            if col==bg or (r,c) in seen: continue
            for dr,dc in ((1,1),(1,-1)):
                chain=[];rr,cc=r,c
                while 0<=rr<h and 0<=cc<w and g[rr][cc]==col and (rr,cc) not in seen:
                    chain.append((rr,cc)); seen.add((rr,cc)); rr+=dr; cc+=dc
                if len(chain)>=2:
                    for p,sgn in ((chain[0],-1),(chain[-1],1)):
                        rr,cc=p
                        while True:
                            rr,cc=rr+sgn*dr,cc+sgn*dc
                            if not(0<=rr<h and 0<=cc<w) or out[rr][cc]!=bg: break
                            out[rr][cc]=col
                else:
                    chain.clear()
    return out
